BEGIN READ ONLY;
SET LOCAL statement_timeout='15s';
WITH roles AS (SELECT oid,rolname FROM pg_roles WHERE rolname IN ('leqvor_governance_auditor','leqvor_governance_control','leqvor_governance_executor'))
SELECT jsonb_build_object(
 'table_matrix',(SELECT jsonb_agg(jsonb_build_object('role',r.rolname,'table',c.relname,'select',has_table_privilege(r.oid,c.oid,'SELECT'),'insert',has_table_privilege(r.oid,c.oid,'INSERT'),'update_table',has_table_privilege(r.oid,c.oid,'UPDATE'),'delete',has_table_privilege(r.oid,c.oid,'DELETE'),'truncate',has_table_privilege(r.oid,c.oid,'TRUNCATE'),'references',has_table_privilege(r.oid,c.oid,'REFERENCES'),'trigger',has_table_privilege(r.oid,c.oid,'TRIGGER'),'maintain',has_table_privilege(r.oid,c.oid,'MAINTAIN'))) FROM roles r CROSS JOIN pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname='founder_governance' AND c.relkind='r'),
 'column_matrix',(SELECT jsonb_agg(jsonb_build_object('role',r.rolname,'table',c.relname,'column',a.attname,'update',has_column_privilege(r.oid,c.oid,a.attnum,'UPDATE'),'update_grant',has_column_privilege(r.oid,c.oid,a.attnum,'UPDATE WITH GRANT OPTION'))) FROM roles r CROSS JOIN pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace JOIN pg_attribute a ON a.attrelid=c.oid WHERE n.nspname='founder_governance' AND c.relkind='r' AND a.attnum>0 AND NOT a.attisdropped),
 'grant_options',(SELECT coalesce(jsonb_agg(jsonb_build_object('table',c.relname,'grantee',pg_get_userbyid(x.grantee),'privilege',x.privilege_type)),'[]') FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace CROSS JOIN LATERAL aclexplode(c.relacl) x WHERE n.nspname='founder_governance' AND x.grantee IN (SELECT oid FROM roles) AND x.is_grantable),
 'ownership',(SELECT jsonb_agg(jsonb_build_object('role',r.rolname,'relations',(SELECT count(*) FROM pg_class WHERE relowner=r.oid),'schemas',(SELECT count(*) FROM pg_namespace WHERE nspowner=r.oid),'functions',(SELECT count(*) FROM pg_proc WHERE proowner=r.oid))) FROM roles r),
 'public_function_default',(SELECT jsonb_agg(jsonb_build_object('owner',r.rolname,'global_public_execute',EXISTS(SELECT 1 FROM aclexplode(coalesce(d.defaclacl,acldefault('f',r.oid))) x WHERE x.grantee=0 AND x.privilege_type='EXECUTE'))) FROM pg_roles r LEFT JOIN pg_default_acl d ON d.defaclrole=r.oid AND d.defaclnamespace=0 AND d.defaclobjtype='f' WHERE r.rolname='neondb_owner'),
 'catalog_security_definers',(SELECT coalesce(jsonb_agg(jsonb_build_object('signature',p.oid::regprocedure::text,'owner',pg_get_userbyid(p.proowner),'config',p.proconfig,'control_execute',has_function_privilege('leqvor_governance_control',p.oid,'EXECUTE'))),'[]') FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname='pg_catalog' AND p.prosecdef),
 'privileged_parameters',(SELECT jsonb_agg(jsonb_build_object('role',r.rolname,'parameter',v.name,'can_set',has_parameter_privilege(r.oid,v.name,'SET'),'can_alter_system',has_parameter_privilege(r.oid,v.name,'ALTER SYSTEM'))) FROM roles r CROSS JOIN (VALUES ('session_replication_role'),('allow_system_table_mods')) v(name)),
 'function_body',(SELECT pg_get_functiondef('founder_governance.reject_audit_mutation()'::regprocedure)),
 'rules',(SELECT coalesce(jsonb_agg(pg_get_ruledef(w.oid)),'[]') FROM pg_rewrite w JOIN pg_class c ON c.oid=w.ev_class JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname='founder_governance'),
 'rls_policies',(SELECT count(*) FROM pg_policies WHERE schemaname='founder_governance')
) AS governance_privilege_detail;
COMMIT;
